-- =====================================================================
--  48_bank_fenn10.sql : 10-CU SINIF - FIZIKA, KIMYA, BIOLOGIYA,
--                      COGRAFIYA
--
--  BU FAYL ELLE YAZILMIR - tools/fenn10.py yaradir:
--      python3 tools/fenn10.py
--
--  Fizika 6 + Kimya 6 + Biologiya 8 + Cografiya 8
--  = 28 movzu x 30 = 840.  ext_key: fiz10-/kim10-/bio10-/cog10-...
--  ON SERT: 45_movzular_orta10.sql islenmis olmalidir.
--  SONRA:   05_grants.sql yeniden islet.
-- =====================================================================

do $$
begin
  if not exists (select 1 from public.topics t join public.subjects s
      on s.id = t.subject_id
     where (s.slug, t.slug) in (('fizika','fiz-10-kinematika'),
                                ('kimya','kim-10-alkan'),
                                ('biologiya','bio-10-genetika'),
                                ('cografiya','cog-10-geologiya'))
     having count(*) = 4) then
    raise exception 'ONCE 45_movzular_orta10.sql isledilmelidir.';
  end if;
end $$;

delete from public.question_options o
 using public.questions q
 where o.question_id = q.id
   and q.owner_type = 'platform'
   and (q.ext_key like 'fiz10-%' or q.ext_key like 'kim10-%'
        or q.ext_key like 'bio10-%' or q.ext_key like 'cog10-%');

